       VALUES ($1,$2,$3,$4,'available') ON CONFLICT DO NOTHING`,
      [name, phone, lic, base]);
  }
  let i = 1;
  for (const [customer, origin, dest, dist, w, v, type, reefer, deadlineH, notes] of orders) {
    const orderNo = `OD2026${String(i).padStart(4, '0')}`;
