const openNewTrip = async (firstOrder, chunkW, chunkV) => {
  // 容量最小且能装下运片的候选车优先（节省大车运力）
  const candidates = vehicles
    .filter(v => !usedVehicles.has(v.id) && typeMatches(v, firstOrder)
      && Number(v.capacity_tons) >= chunkW - 1e-6
      && Number(v.capacity_volume) >= chunkV - 1e-6)
    .sort((a, b) => Number(a.capacity_tons) - Number(b.capacity_tons));

  let deadlineOk = false;
  for (const v of candidates) {
    const { arrive } = planArrival(start, chunkW, Number(firstOrder.distance_km));
    if (arrive > new Date(firstOrder.deadline)) continue;
    deadlineOk = true;
    const driver = drivers.find(d => !usedDrivers.has(d.id) && driverCanDrive(d, v));
    if (!driver) continue;

    const { rows: tr } = await client.query(
      `INSERT INTO trips (trip_no, vehicle_id, driver_id, origin, destination, distance_km,
                          status, planned_depart, planned_arrive)
       VALUES ($1,$2,$3,$4,$5,$6,'planned',$7,$8) RETURNING *`,
      [genTripNo(), v.id, driver.id, firstOrder.origin, firstOrder.destination,
       firstOrder.distance_km, null, null]);
    usedVehicles.add(v.id);
    usedDrivers.add(driver.id);
    await client.query(`UPDATE vehicles SET status='assigned' WHERE id=$1`, [v.id]);
    await client.query(`UPDATE drivers SET status='on_trip' WHERE id=$1`, [driver.id]);
    openTrips.push({
      trip: tr[0], vehicle: v, loadedW: 0, loadedV: 0, orders: [],
      distance: Number(firstOrder.distance_km), deadline: new Date(firstOrder.deadline),
    });
    return { trip: openTrips[openTrips.length - 1] };
  }
  return { reason: deadlineOk ? 'no_driver' : 'deadline' };
};

const addItem = async (slot, item, w, v) => {
  const t = slot;
  await client.query(
    `INSERT INTO trip_items (trip_id, order_id, weight_tons, volume_m3)
     VALUES ($1,$2,$3,$4)
     ON CONFLICT (trip_id, order_id) DO UPDATE
     SET weight_tons = trip_items.weight_tons + EXCLUDED.weight_tons,
         volume_m3 = trip_items.volume_m3 + EXCLUDED.volume_m3`,
    [t.trip.id, item.order.id, w, v]);
  t.loadedW += w; t.loadedV += v;
  if (!t.orders.includes(item.order.id)) t.orders.push(item.order.id);
};

const refreshPlan = async (t) => {
  const { arrive, depart } = planArrival(start, t.loadedW, t.distance, 0);
  t.depart = depart; t.arrive = arrive;
  await client.query(
    `UPDATE trips SET planned_depart=$1, planned_arrive=$2 WHERE id=$3`,
    [depart, arrive, t.trip.id]);
};

for (const [, group] of [...groups].sort((a, b) =>
  Math.min(...a[1].map(i => new Date(i.order.deadline))) -
  Math.min(...b[1].map(i => new Date(i.order.deadline))))) {

  // 大件优先，提高拼箱率
  group.sort((a, b) => b.remainW - a.remainW);

