/**
 * 车辆偏好分：越小越优先
 * - 冷藏车只留给冷链货（非冷链货用冷藏车重罚）
 * - 指定车型的订单优先用同型车，其次用更大的非冷藏车
 * - 容量越贴合运片越优先（节省大车运力）
 */
const prefScore = (v, order, chunkW) => {
  let score = Number(v.capacity_tons);
  if (order.require_reefer) {
    if (v.vehicle_type === 'reefer') score -= 100;
  } else {
    if (v.vehicle_type === 'reefer') score += 500;
    if (order.required_type !== 'any') {
      if (v.vehicle_type === order.required_type) score -= 100;
    }
  }
  score += Math.abs(Number(v.capacity_tons) - chunkW) * 2;
  return score;
};

input.new_string:
/**
 * 车辆偏好分：越小越优先
 * 1) 容量档位：能装下运片的最小车型（避免小车装不下被迫拆片，也避免大车浪费）
 * 2) 同档位下：指定车型优先；非冷链货避开冷藏车；冷链货必须冷藏
 */
const prefScore = (v, order, chunkW) => {
  let score = 0;
  const cap = Number(v.capacity_tons);
  if (order.require_reefer) {
    if (v.vehicle_type !== 'reefer') return Infinity;
    score += cap; // 容量贴合
  } else {
    if (v.vehicle_type === 'reefer') score += 10000; // 冷藏车留给冷链货
    score += cap * 10; // 容量档位主导：小车优先
    if (order.required_type !== 'any') {
      score += v.vehicle_type === order.required_type ? -50 : 30;
    }
  }
  score += Math.abs(cap - chunkW) * 0.5; // 同档内贴合度
  return score;
};

