/** 司机驾照是否能开该车 */
function driverCanDrive(driver, vehicle) {
  const rank = { C1: 1, B1: 2, A2: 3 };
  return (rank[driver.license_type] || 0) >= (rank[VEHICLE_META[vehicle.vehicle_type].license] || 9);
}

/**
 * 挑选司机：能用低等级驾照开就不占用 A2（把 A2 留给大卡），
 * 同等级中优先工时少的。
 */
function pickDriver(drivers, usedDrivers, vehicle) {
  const rank = { C1: 1, B1: 2, A2: 3 };
  const need = rank[VEHICLE_META[vehicle.vehicle_type].license] || 9;
  const eligible = drivers
    .filter(d => !usedDrivers.has(d.id) && (rank[d.license_type] || 0) >= need)
    .sort((a, b) => (rank[a.license_type] - rank[b.license_type])
      || (Number(a.worked_hours) - Number(b.worked_hours)));
  return eligible[0] || null;
}

