const addItem = async (slot, item, w, v) => {
  const t = slot;
  await client.query(
    `INSERT INTO trip_items (trip_id, order_id, weight_tons, volume_m3)
     VALUES ($1,$2,$3,$4)
     ON CONFLICT (trip_id, order_id) DO UPDATE
     SET weight_tons = trip_items.weight_tons + EXCLUDED.weight_tons,
         volume_m3 = trip_items.volume_m3 + EXCLUDED.volume_m3`,
    [t.trip.id, item.order.id, w, v]);
  t.loadedW += w; t.loadedV += v;
  if (!t.orders.includes(item.order.id)) t.orders.push(item.order.id);
};

const refreshPlan = async (t) => {
  const { arrive, depart } = planArrival(start, t.loadedW, t.distance, 0);
  t.depart = depart; t.arrive = arrive;
  await client.query(
    `UPDATE trips SET planned_depart=$1, planned_arrive=$2 WHERE id=$3`,
    [depart, arrive, t.trip.id]);
};

for (const [, group] of [...groups].sort((a, b) =>
  Math.min(...a[1].map(i => new Date(i.order.deadline))) -
  Math.min(...b[1].map(i => new Date(i.order.deadline))))) {

  // 大件优先，提高拼箱率
  group.sort((a, b) => b.remainW - a.remainW);

  for (const item of group) {
    let w = item.remainW, v = item.remainV;
    let placedWhole = false;
    const touchedTrips = new Set();

    while (w > 0.001 || v > 0.001) {
      // 在同路线已开放车次中寻找可装入且不突破时限的，剩余容量最贴合者优先（best-fit 拼车）
      let fit = null;
      let fitRoom = Infinity;
      for (const t of openTrips) {
        if (t.trip.origin !== item.order.origin || t.trip.destination !== item.order.destination) continue;
        if (!typeMatches(t.vehicle, item.order)) continue;
        const roomW = Number(t.vehicle.capacity_tons) - t.loadedW;
        const roomV = Number(t.vehicle.capacity_volume) - t.loadedV;
        if (roomW + 1e-6 < w || roomV + 1e-6 < v) continue;
        // 加入后是否仍能在本订单截止前到达
        const { arrive } = planArrival(start, t.loadedW + w, t.distance);
        if (arrive > new Date(item.order.deadline)) continue;
        // 非冷链货不拼进冷藏车次；冷链货只进冷藏车次
        if (!item.order.require_reefer && t.vehicle.vehicle_type === 'reefer') continue;
        if (roomW < fitRoom) { fitRoom = roomW; fit = t; }
      }

      if (fit) {
        await addItem(fit, item, w, v);
        await refreshPlan(fit);
        touchedTrips.add(fit);
        w = 0; v = 0; placedWhole = true;
      } else {
        // 开新车；若整车装不下（订单大于任何车），按最大可用车容量拆片
        const eligible = vehicles
          .filter(x => !usedVehicles.has(x.id) && typeMatches(x, item.order));
        if (!eligible.length) {
          result.unmet.push({ order_no: item.order.order_no, reason: '无可用车型车辆', remaining_tons: +w.toFixed(2) });
          break;
        }
        // 最优偏好类别中选容量最大的车，减少拆片数
        const best = Math.min(...eligible.map(x => prefScore(x, item.order, w)));
        const biggest = eligible
          .filter(x => prefScore(x, item.order, w) <= best + 0.01)
          .sort((a, b) => Number(b.capacity_tons) - Number(a.capacity_tons))[0];
        const roomW = Number(biggest.capacity_tons);
        const roomV = Number(biggest.capacity_volume);
        const chunkW = Math.min(w, roomW);
        // 体积按重量等比例切
        const chunkV = w > 0 ? Math.min(v, v * (chunkW / w)) : Math.min(v, roomV);

        const opened = await openNewTrip(item.order, chunkW, chunkV);
        if (opened.reason) {
          result.unmet.push({
            order_no: item.order.order_no,
            reason: opened.reason === 'deadline' ? '即使立即派车也无法在截止时间前送达'
                  : opened.reason === 'no_driver' ? '无可用准驾司机' : '无可用车辆',
            remaining_tons: +w.toFixed(2),
          });
          break;
        }
        await addItem(opened.trip, item, chunkW, chunkV);
        await refreshPlan(opened.trip);
        touchedTrips.add(opened.trip);
        result.tripsCreated++;
        w -= chunkW; v -= chunkV;
        if (w <= 0.001 && v <= 0.001) placedWhole = true;
      }
    }

    // 更新订单状态
    if (w <= 0.001 && v <= 0.001) {
      const split = !placedWhole || item.order.status === 'split';
      await client.query(
        `UPDATE orders SET status = $1 WHERE id = $2`,
        [split ? 'split' : 'assigned', item.order.id]);
      if (split) result.ordersSplit++; else result.ordersAssigned++;
    } else if (item.order.status !== 'split') {
      // 部分派车
      await client.query(`UPDATE orders SET status='split' WHERE id=$1`, [item.order.id]);
      result.ordersSplit++;
    }
  }
}

await client.query('COMMIT');

