import { pool } from '../db/pool.js';

const SPEED_KMH = Number(process.env.AVERAGE_SPEED_KMH || 55);
const LOAD_MIN_PER_TON = Number(process.env.LOADING_MINUTES_PER_TON || 15);

// 车型 -> 所需驾照 / 展示名
export const VEHICLE_META = {
  small:  { label: '小型货车', license: 'C1', maxTons: 2 },
  medium: { label: '中型货车', license: 'B1', maxTons: 8 },
  large:  { label: '大型货车', license: 'A2', maxTons: 30 },
  reefer: { label: '冷藏车',   license: 'B1', maxTons: 10 },
};

export const ORDER_STATUS = {
  pending: '待调度', assigned: '已派车', loading: '装车中',
  in_transit: '运输中', delivered: '已签收', split: '已拆分',
  cancelled: '已取消', late: '已延误/逾期',
};

const now = () => new Date();
const addMinutes = (d, m) => new Date(d.getTime() + m * 60000);

/** 行程时间（分钟） */
function travelMinutes(distanceKm) {
  return Math.round((distanceKm / SPEED_KMH) * 60);
}
/** 装车时间（分钟），按吨位估算 */
function loadingMinutes(tons) {
  return Math.round(tons * LOAD_MIN_PER_TON);
}

const LICENSE_RANK = { C1: 1, B1: 2, A2: 3 };

/** 车辆是否满足订单车型要求 */
function typeMatches(vehicle, order) {
  if (order.require_reefer) return vehicle.vehicle_type === 'reefer';
  if (order.required_type === 'any') return vehicle.vehicle_type !== 'reefer'; // 冷藏车不参与普货兜底
  return vehicle.vehicle_type === order.required_type;
}

/** 司机驾照是否能开该车 */
function driverCanDrive(driver, vehicle) {
  return (LICENSE_RANK[driver.license_type] || 0)
    >= (LICENSE_RANK[VEHICLE_META[vehicle.vehicle_type].license] || 9);
}

/**
 * 挑选司机：能用低等级驾照开就不占用 A2（把 A2 留给大卡），
 * 同等级中优先工时少的。
 */
function pickDriver(drivers, usedDrivers, vehicle) {
  const need = LICENSE_RANK[VEHICLE_META[vehicle.vehicle_type].license] || 9;
  return drivers
    .filter(d => !usedDrivers.has(d.id) && (LICENSE_RANK[d.license_type] || 0) >= need)
    .sort((a, b) => (LICENSE_RANK[a.license_type] - LICENSE_RANK[b.license_type])
      || (Number(a.worked_hours) - Number(b.worked_hours)))[0] || null;
}

/** 按 start 起算：装车 + 行驶后的预计到达 */
function planArrival(start, totalTons, distanceKm, delayMin = 0) {
  const depart = addMinutes(start, loadingMinutes(totalTons));
  return { depart, arrive: addMinutes(depart, travelMinutes(distanceKm) + delayMin) };
}

let tripSeq = 0;
function genTripNo() {
  const d = new Date();
  const p = n => String(n).padStart(2, '0');
  const seq = String(++tripSeq).padStart(3, '0');
  return `TR${d.getFullYear()}${p(d.getMonth() + 1)}${p(d.getDate())}${p(d.getHours())}${p(d.getMinutes())}${p(d.getSeconds())}${seq}${Math.floor(Math.random() * 90 + 10)}`;
}

// ---------------------------------------------------------------------------
// 自动调度（两阶段 FFD + best-fit 装箱）
// ---------------------------------------------------------------------------

/**
 * 阶段一（strict=true）：只用「最优车型」——指定车型单必须同型；不限车型单按
 *   重量选最小可容纳车型；冷链单必须冷藏车。
 * 阶段二（strict=false）：剩余运片可用任意兼容车型兜底（普货不占冷藏车）。
 * 同一阶段内：按路线分组 → 组内大件优先（FFD）→ 先拼已开车次（best-fit，受
 *   重量/体积/时限约束）→ 拼不下再开新车 → 单车装不下则按容量拆片。
 */
export async function autoDispatch() {
  const client = await pool.connect();
  try {
    await client.query('BEGIN');

    const { rows: orders } = await client.query(
      `SELECT * FROM orders WHERE status IN ('pending','split') ORDER BY deadline ASC FOR UPDATE`);
    const { rows: vehicles } = await client.query(
      `SELECT * FROM vehicles WHERE status = 'available' ORDER BY capacity_tons ASC FOR UPDATE`);
    const { rows: drivers } = await client.query(
      `SELECT * FROM drivers WHERE status = 'available' ORDER BY worked_hours ASC FOR UPDATE`);

    // 仅把还没有运片的部分纳入调度（split 订单可能已有部分运片）
    const items = [];
    for (const o of orders) {
      const { rows: assigned } = await client.query(
        `SELECT COALESCE(SUM(weight_tons),0) AS w, COALESCE(SUM(volume_m3),0) AS v
         FROM trip_items ti JOIN trips t ON t.id = ti.trip_id
         WHERE ti.order_id = $1 AND t.status <> 'cancelled'`, [o.id]);
      const remainW = Number(o.weight_tons) - Number(assigned[0].w);
      const remainV = Number(o.volume_m3) - Number(assigned[0].v);
      if (remainW > 0.001 || remainV > 0.001) {
        items.push({ order: o, remainW, remainV });
      }
    }

    const usedVehicles = new Set();
    const usedDrivers = new Set();
    /** 运行中的车次：{ trip, vehicle, loadedW, loadedV, origin, destination, distance } */
    const openTrips = [];
    /** 订单 -> 运片数（用于区分整单/拆单） */
    const chunkCount = new Map();
    const unmet = [];
    let tripsCreated = 0;
    const start = now();

    /** 严格阶段的最优车型集合 */
    const preferredTypes = (order, chunkW) => {
      if (order.require_reefer) return ['reefer'];
      if (order.required_type !== 'any') return [order.required_type];
      // 不限车型：按重量选最小非冷藏车型
      if (chunkW <= VEHICLE_META.small.maxTons) return ['small'];
      if (chunkW <= VEHICLE_META.medium.maxTons) return ['medium'];
      return ['large'];
    };

    const isAllowed = (v, order, strict) => {
      if (usedVehicles.has(v.id)) return false;
      if (strict) return preferredTypes(order, v.__chunkW || 0).includes(v.vehicle_type)
        && typeMatches(v, order);
      return typeMatches(v, order);
    };

    /** 在同路线已开车次中找可拼入的车次（best-fit：剩余容量最小） */
    const findOpenTrip = (order, w, v) => {
      let fit = null, fitRoom = Infinity;
      for (const t of openTrips) {
        if (t.origin !== order.origin || t.destination !== order.destination) continue;
        if (!typeMatches(t.vehicle, order)) continue;
        const roomW = Number(t.vehicle.capacity_tons) - t.loadedW;
        const roomV = Number(t.vehicle.capacity_volume) - t.loadedV;
        if (roomW + 1e-6 < w || roomV + 1e-6 < v) continue;
        const { arrive } = planArrival(start, t.loadedW + w, t.distance);
        if (arrive > new Date(order.deadline)) continue;
        if (!order.require_reefer && t.vehicle.vehicle_type === 'reefer') continue;
        if (roomW < fitRoom) { fitRoom = roomW; fit = t; }
      }
      return fit;
    };

    const pickVehicle = (order, chunkW, strict) => {
      const cands = vehicles
        .filter(x => !usedVehicles.has(x.id) && typeMatches(x, order)
          && Number(x.capacity_tons) >= chunkW - 1e-6)
        .filter(x => {
          if (!strict) return true;
          return preferredTypes(order, chunkW).includes(x.vehicle_type);
        })
        // 容量最贴合优先；同容量小车场的优先无意义，取容量升序即可
        .sort((a, b) => Number(a.capacity_tons) - Number(b.capacity_tons));
      return cands[0] || null;
    };

    const createTrip = async (order, vehicle, chunkW, chunkV) => {
      const driver = pickDriver(drivers, usedDrivers, vehicle);
      if (!driver) return { error: 'no_driver' };
      const { arrive } = planArrival(start, chunkW, Number(order.distance_km));
      if (arrive > new Date(order.deadline)) return { error: 'deadline' };

      const { rows: tr } = await client.query(
        `INSERT INTO trips (trip_no, vehicle_id, driver_id, origin, destination, distance_km,
                            status, planned_depart, planned_arrive)
         VALUES ($1,$2,$3,$4,$5,$6,'planned',$7,$8) RETURNING *`,
        [genTripNo(), vehicle.id, driver.id, order.origin, order.destination,
         order.distance_km, null, null]);
      usedVehicles.add(vehicle.id);
      usedDrivers.add(driver.id);
      await client.query(`UPDATE vehicles SET status='assigned' WHERE id=$1`, [vehicle.id]);
      await client.query(`UPDATE drivers SET status='on_trip' WHERE id=$1`, [driver.id]);
      const slot = {
        trip: tr[0], vehicle, loadedW: 0, loadedV: 0,
        origin: order.origin, destination: order.destination,
        distance: Number(order.distance_km),
      };
      openTrips.push(slot);
      tripsCreated++;
      return { slot };
    };

    const attachItem = async (slot, item, w, v) => {
      await client.query(
        `INSERT INTO trip_items (trip_id, order_id, weight_tons, volume_m3)
         VALUES ($1,$2,$3,$4)
         ON CONFLICT (trip_id, order_id) DO UPDATE
         SET weight_tons = trip_items.weight_tons + EXCLUDED.weight_tons,
             volume_m3 = trip_items.volume_m3 + EXCLUDED.volume_m3`,
        [slot.trip.id, item.order.id, w, v]);
      slot.loadedW += w;
      slot.loadedV += v;
      const { depart, arrive } = planArrival(start, slot.loadedW, slot.distance);
      await client.query(
        `UPDATE trips SET planned_depart=$1, planned_arrive=$2 WHERE id=$3`,
        [depart, arrive, slot.trip.id]);
      chunkCount.set(item.order.id, (chunkCount.get(item.order.id) || 0) + 1);
    };

    // 按路线分组，组按最早截止时间排序
    const groups = new Map();
    for (const it of items) {
      const key = `${it.order.origin}=>${it.order.destination}`;
      if (!groups.has(key)) groups.set(key, []);
      groups.get(key).push(it);
    }
    const sortedGroups = [...groups.values()].sort((a, b) =>
      Math.min(...a.map(i => new Date(i.order.deadline)))
      - Math.min(...b.map(i => new Date(i.order.deadline))));

    const placeItem = (item, strict) => {
      // 返回 { placed: 已放置重量, remaining, reason? }，同步完成资源决策，DB 写入异步
      return null; // 占位，实际内联在两阶段循环中
    };

    for (const strict of [true, false]) {
      for (const group of sortedGroups) {
        // FFD：大件优先
        const queue = group
          .filter(it => it.remainW > 0.001 || it.remainV > 0.001)
          .sort((a, b) => b.remainW - a.remainW);

        for (const item of queue) {
          let w = item.remainW, v = item.remainV;
          let guard = 0;

          while ((w > 0.001 || v > 0.001) && guard++ < 50) {
            // 1) 先拼已开车次（整车放入）
            const fit = findOpenTrip(item.order, w, v);
            if (fit) {
              await attachItem(fit, item, w, v);
              item.remainW = 0; item.remainV = 0; w = 0; v = 0;
              break;
            }

            // 2) 开新车：选本阶段允许的、容量最小且装得下的车
            const vehicle = pickVehicle(item.order, w, strict);
            if (!vehicle) break; // 本阶段无车，留到下一阶段或 unmet

            const capW = Number(vehicle.capacity_tons);
            const capV = Number(vehicle.capacity_volume);
            const chunkW = Math.min(w, capW);
            const chunkV = w > 0.001 ? Math.min(v, v * (chunkW / w)) : Math.min(v, capV);

            if (chunkV > capV + 1e-6) {
              // 体积先满：按体积比例反切（泡货）
              const byVol = w * (capV / v);
              const r = await createTrip(item.order, vehicle, Math.min(w, byVol), capV);
              if (r.error) {
                if (r.error === 'deadline') { /* 换车也可能来不及；跳出由兜底阶段处理 */ }
                break;
              }
              const cw = Math.min(w, byVol);
              await attachItem(r.slot, item, cw, capV);
              w -= cw; v -= capV;
              item.remainW = w; item.remainV = v;
              continue;
            }

            const r = await createTrip(item.order, vehicle, chunkW, chunkV);
            if (r.error === 'no_driver') {
              // 准驾司机不足：该车不可用，换同型下一辆
              usedVehicles.add(vehicle.id); // 临时屏蔽，避免死循环；本阶段结束不影响 DB（车未改状态）
              continue;
            }
            if (r.error === 'deadline') {
              usedVehicles.add(vehicle.id);
              continue;
            }
            await attachItem(r.slot, item, chunkW, chunkV);
            w -= chunkW; v -= chunkV;
            item.remainW = w; item.remainV = v;
          }
        }
      }
    }

    // 汇总未满足运量并更新订单状态
    let ordersAssigned = 0, ordersSplit = 0;
    for (const it of items) {
      if (it.remainW > 0.001 || it.remainV > 0.001) {
        // 判断原因
        const anyVehicle = vehicles.some(x => typeMatches(x, it.order));
        const reason = !anyVehicle ? '无可用车型车辆'
          : !drivers.some(d => typeMatches && drivers.some(dd =>
              driverCanDrive(dd, { vehicle_type:
                it.order.require_reefer ? 'reefer' : (it.order.required_type === 'any' ? 'large' : it.order.required_type) })))
            ? '无可用准驾司机'
            : checkDeadlineReason(it.order);
        unmet.push({ order_no: it.order.order_no, reason, remaining_tons: +it.remainW.toFixed(2) });
      }
      const chunks = chunkCount.get(it.order.id) || 0;
      if (it.remainW <= 0.001 && it.remainV <= 0.001) {
        const split = chunks > 1 || it.order.status === 'split';
        await client.query(`UPDATE orders SET status=$1 WHERE id=$2`,
          [split ? 'split' : 'assigned', it.order.id]);
        if (split) ordersSplit++; else ordersAssigned++;
      } else if (chunks > 0) {
        await client.query(`UPDATE orders SET status='split' WHERE id=$1`, [it.order.id]);
        ordersSplit++;
      }
    }

    function checkDeadlineReason(order) {
      const biggest = vehicles
        .filter(x => typeMatches(x, order))
        .sort((a, b) => Number(b.capacity_tons) - Number(a.capacity_tons))[0];
      if (!biggest) return '无可用车型车辆';
      const { arrive } = planArrival(start, Number(biggest.capacity_tons), Number(order.distance_km));
      return arrive > new Date(order.deadline) ? '即使立即派车也无法在截止时间前送达' : '运力或准驾司机不足';
    }

    await client.query('COMMIT');
    return { tripsCreated, ordersAssigned, ordersSplit, unmet };
  } catch (e) {
    await client.query('ROLLBACK');
    throw e;
  } finally {
    client.release();
  }
}

