        `SELECT v.* FROM vehicles v
         WHERE v.status IN ('available','assigned') AND v.vehicle_type = $1
           AND v.capacity_tons >= (
             SELECT COALESCE(SUM(weight_tons),0) FROM trip_items WHERE trip_id=$2)
